// Dávka F – Oslavy a svátky (narozeniny, Ježíšek, Mikuláš, Velikonoce, lampiony, karneval)
window.STORIES_DRAFT = (window.STORIES_DRAFT || []).concat([
  {
    id: 'narozeninove-prani',
    delka: 10,
    pro: 'vse',
    pozn: 'Hrdina slaví narozeniny. Dárky má rozbalené už v osm ráno a pak dostane prázdnou „sklenici na chvilky“, do které celý den chytá společné chvíle: písničku u postele, bunkr z dek, oslavu s kamarády a svíčky na dortu. Kamarádce Emě nejdřív za malovaný kamínek jen rychle řekne „jo, dík“, pak se vrátí a poděkuje doopravdy.',
    pouceni: 'Nejcennější dárek je čas strávený spolu. Poděkovat doopravdy znamená říct, co mě potěšilo.',
    free: false,
    cats: ['svatky', 'zivot'],
    ages: [2, 7],
    mood: 'adventure',
    cover: { emoji: '🎂', g1: '#ffb74d', g2: '#f8bbd0' },
    title: () => `Narozeninové přání`,
    text: (c) => {
      const g = c.g, n = c.n, p = c.p1, q = c.p2 || c.p1;
      return [
        { t: `Ještě než zazvonil budík, tiše zavrzaly dveře. Do pokoje připlula vůně kakaa a za ní písnička, kterou zná každý: „Hodně štěstí, zdraví…“`, sfx: 'birds' },
        { t: `Dnes ${n('má', 'mají')} narozeniny ${c.H}!` },
        { t: `${cap(p.full)} ${p.g('seděl', 'seděla')} na kraji postele a ${p.g('zpíval', 'zpívala')}.${c.p2 ? ` ${cap(c.p2.full)} ${c.p2.g('přidal', 'přidala')} druhý hlas.` : ''}` },
        { t: `Trochu falešně, ale zato pořádně nahlas, až se na poličce zhoupl plyšový medvěd. Byla to ta nejkrásnější písnička na světě. Ta, která se zpívá jen jednou za rok.` },
        { t: `Potom přišly na řadu dárky. Čekaly na stole v obýváku, zabalené do papíru s balónky. Jeden velký, dva prostřední a jeden úplně maličký, schovaný vzadu za vázou.` },
        { t: `${c.H} se do nich ${g('pustil', 'pustila', 'pustili')} jako vítr do listí.` },
        { t: `Ríp! Papír letěl doleva. Rup! Mašle letěla doprava. Stavebnice s věží! Knížka o zvířatech z celého světa! Krabice pastelek ve dvou patrech!`, sfx: 'paper' },
        { t: `Stavebnice se postavila za pět minut. Knížka se prolistovala za tři. Pastelky se vyzkoušely všechny, každá jednou čárkou.` },
        { t: `A pak bylo najednou ticho. Na koberci ležela hora papíru, na lustru visela mašle a hodiny ukazovaly teprve osm. V hlavě se ozvala malá otázka: „To už je všechno?“ A hned za ní druhá, ještě menší: „A co ${n('budu', 'budeme')} dělat celý zbytek dne?“` },
        { t: `Na stole ale zůstal ještě ten maličký dárek. Byl zabalený do hnědého papíru a převázaný obyčejným provázkem. Uvnitř byla sklenice. Prázdná sklenice od okurek, čistě umytá, s víčkem. Na ní štítek a na štítku nápis: Sklenice na chvilky.` },
        { t: `„Prázdná?“ ${g('podivil', 'podivila', 'podivili')} se ${c.H}.` },
        { t: `„Zatím,“ ${p.g('usmál', 'usmála')} se ${p.nom}.` },
        { t: `„Do téhle sklenice se chytají chvilky, které se nedají koupit v žádném obchodě. Když se stane něco hezkého, otevře se víčko a zase se zavře. Cvak. A večer se podíváme, co ${g('jsi nachytal', 'jsi nachytala', 'jste nachytali')}.“` },
        { t: `Víčko se zkusmo otevřelo. Chvíli se nedělo nic. A pak, jako by si to sklenice sama rozmyslela, se ozvalo: cvak! Uvnitř byla první chvilka. Ta ranní, s písničkou u postele a s vůní kakaa.`, sfx: 'magic' },
        { t: `Dopoledne začalo pršet. Kapky bubnovaly do okna, na hřiště se nedalo a nová stavebnice už byla postavená dvakrát a dvakrát zbořená.` },
        { t: `${cap(q.nom)} se ${q.g('rozhlédl', 'rozhlédla')} po obýváku.` },
        { t: `„${n('Víš', 'Víte')}, co se dělá, když prší? Staví se bunkr!“` },
        { t: `Židle byly zdi, deka byla střecha a polštáře byly dveře. Uvnitř byla tma, baterka a nová knížka o zvířatech. Do bunkru se vešli všichni, i když kolena trochu trčela ven.` },
        { t: `Četlo se o tučňácích. Někteří tučňáci hledají na pláži ten nejhladší kamínek, jaký najdou. A ten pak darují tomu, koho mají nejradši. Z kamínků si spolu postaví hnízdo.` },
        { t: `„Kamínek jako dárek?“ ozvalo se z jednoho konce bunkru. „Pro tučňáka ten nejvzácnější,“ ozvalo se z druhého. Cvak! Druhá chvilka.` },
        { t: `Po obědě přestalo pršet. Na chodníku zůstaly louže, kulaté a lesklé jako zrcadla. A kdo má narozeniny, ten smí skákat do louží. To je takové staré narozeninové pravidlo.` },
        { t: `Holínky na nohy a hop! Šplouch! Pak větší louže. ŠPLOUCH! A nakonec ta největší na celé ulici, ta u lampy, ve které se zrcadlilo nebe i s mraky.` },
        { t: `Skákalo se, dokud nebyly mokré ponožky, kalhoty i čepice. Jedna kapka doletěla až na nos sousedovu kocourovi a ten se tvářil uraženě až do večera. Cvak! Třetí chvilka, mokrá a rozcákaná smíchem.` },
        { t: `Odpoledne vysvitlo slunce a zazvonil zvonek. Crrr! Přišli kamarádi.`, sfx: 'ding' },
        { t: `Kuba přinesl velkou krabici s mašlí. Jonáš přinesl krabici ještě větší. A Ema přinesla jen malý uzlíček zabalený do kapesníku.` },
        { t: `V Kubově krabici bylo auto na ovládání. V Jonášově míč, který svítí ve tmě. A v Emině kapesníku byl kamínek. Hladký, kulatý a pomalovaný jako beruška: červený, s černými tečkami a dvěma tenkými tykadly.` },
        { t: `„Jo, dík,“ ${g('řekl', 'řekla', 'řekli')} ${c.H}. A už se ${g('hnal', 'hnala', 'hnali')} zkoušet auto.` },
        { t: `Auto bzučelo pod stolem, míč svítil pod gaučem a všichni výskali. Jen Ema seděla na kraji pohovky a mlčela. Beruška ležela na stole úplně sama, mezi zmačkaným papírem od dárků.` },
        { t: `A v tu chvíli to uvnitř malinko píchlo. Kamínek. Ten nejhladší a nejkulatější. Ten se přece nedává jen tak. Ten se dává tomu, koho má člověk nejradši.` },
        { t: `${c.H} ${g('vzal', 'vzala', 'vzali')} berušku do ${n('dlaně', 'dlaní')} a ${g('sedl', 'sedla', 'sedli')} si k Emě.` },
        { t: `„Malovala jsi ji sama?“ Ema kývla. „Celé odpoledne. Nejtěžší byla tykadla. Pořád mi utíkala.“` },
        { t: `„${n('Děkuju', 'Děkujeme')}. Je to ta nejhezčí beruška, jakou ${g('jsem kdy viděl', 'jsem kdy viděla', 'jsme kdy viděli')}. Bude bydlet vedle postele a hlídat sny.“` },
        { t: `Ema se rozzářila jako lampion. Cvak! Čtvrtá chvilka. A divná věc: tahle se do sklenice chytila, i když se zrovna nic nerozbalovalo.` },
        { t: `Potom se hrál tučňáčí závod. Každý dostal mezi kolena míček a musel s ním docupitat ke dveřím a zpátky. Jonáš upadl, Kubovi míček vyklouzl smíchy a Ema vyhrála, protože cupitala nejvážněji ze všech.` },
        { t: `Pak se hrálo na sochy. Hudba hrála a všichni tancovali, hudba zmlkla a všichni ztuhli. Jonáš ztuhl na jedné noze jako čáp. Kuba ztuhl s otevřenou pusou a smál se tak, že musel vypadnout. A Ema stála jako opravdová socha, jen copánky se jí třásly.` },
        { t: `Když se kamarádi loučili, Ema se ve dveřích ještě otočila. „Ta beruška umí v noci létat,“ zašeptala. „Ale jen když se nikdo nedívá.“` },
        { t: `Pak se zatáhly závěsy a z kuchyně připlul dort. Hořely na něm svíčky, jedna za každý rok.` },
        { t: `Na stole nechybělo ani to nejlepší jídlo na světě: ${c.food}.` },
        { t: `„Přání!“ volali všichni. „Ale potichu, jinak se nesplní!“` },
        { t: `${c.H} ${g('zavřel', 'zavřela', 'zavřeli')} oči.` },
        { t: `Co si přát? Hračky už jsou. Knížka je. Auto jezdí. A pak to přišlo samo. Přání se nahlas neříká, a tak ho neprozradíme ani tady. Jen tolik: bylo malé a vešlo by se do sklenice.` },
        { t: `Fffff! Svíčky zhasly všechny najednou a z knotů se vznesly tenké stužky kouře. Cvak! Pátá chvilka.`, sfx: 'sparkle' },
        { t: `Večer, když kamarádi odešli, zbyly po oslavě jen drobky, jedna zapomenutá mašle na lustru a velká únava v nohou. Sklenice stála na nočním stolku vedle berušky. Byla úplně průhledná a úplně prázdná. Nebo ne?` },
        { t: `„Tak co ${g('jsi nachytal', 'jsi nachytala', 'jste nachytali')}?“ ${p.g('zeptal', 'zeptala')} se ${p.nom}.` },
        { t: `Víčko cvaklo a chvilky se začaly vracet. Ranní písnička. Bunkr z dek a tučňáci s kamínky. Louže u lampy. Emina beruška. Svíčky, které zhasly naráz. Každou bylo potřeba vyprávět. A když se vyprávěla, byla zase celá živá, jako by se stala právě teď.` },
        { t: `Nejdéle se vyprávěla louže u lampy. Při vyprávění rostla a rostla, až z ní byl skoro rybník. Tak to s chvilkami bývá. Když se vyprávějí, trochu vyrostou.` },
        { t: `Na konci přišlo ještě poděkování. Ne rychlé „jo, dík“, ale pořádné.` },
        { t: `„${n('Děkuju', 'Děkujeme')} za ranní písničku. I za tu falešnou notu. ${n('Děkuju', 'Děkujeme')} za bunkr a za tučňáky. A za to, že jsme byli celý den spolu.“` },
        { t: `${cap(p.nom)} nic ${p.g('neřekl', 'neřekla')}. Jen objetí bylo tak pevné, že to cvaklo i bez sklenice.` },
        { t: `Sklenice stojí na stolku dodnes. Vypadá prázdná, ale je plná až po víčko. Takové sklenice mají jednu zvláštnost: chvilky z nich nikdy nedojdou, dokud je někdo vypráví. A beruška vedle sklenice? Ta jen čeká, až se nikdo nebude dívat.` },
        { t: `Dobrou noc, ${g('oslavenče', 'oslavenkyně', 'oslavenci', 'oslavenkyně')}. Dobrou noc, ${c.h.voc}.`, pause: 3 },
      ];
    },
  },
  {
    id: 'jeziskova-posta',
    delka: 15,
    pro: 'vse',
    pozn: 'Mladý vítr Vichřík nese dopisy pro Ježíška, kýchne a rozfouká je po okolí. Sníh rozmazal jména, a tak hrdina podle stop (mouka, cedulka na psí boudě, malé holínky) zjišťuje, čí dopis je. Dozví se, co si přejí ostatní, a jedno přání, návštěvu u osamělé paní Vlasty, splní sám. Ježíška nikdo nevidí, tajemství zůstává.',
    pouceni: 'Dávat je stejně krásné jako dostávat a některá přání můžeme splnit sami, stačí chvilka času.',
    free: false,
    cats: ['svatky', 'dobro'],
    ages: [3, 8],
    mood: 'adventure',
    cover: { emoji: '✉️', g1: '#1a237e', g2: '#90caf9' },
    title: () => `Ježíškova ztracená pošta`,
    text: (c) => {
      const g = c.g, n = c.n, p = c.p1;
      const far = c.near[0] ? `Až za kopec, tam, kde leží ${c.near[0]}.` : `Až za kopec, k sousední vesnici.`;
      return [
        { t: `Venku padal první sníh. Takový ten opatrný, který si ještě není jistý, jestli smí zůstat ležet.` },
        { t: `${c.H} ${g('seděl', 'seděla', 'seděli')} u stolu nad dopisem pro Ježíška.` },
        { t: `Psalo se pastelkami, a kde písmenka nestačila, tam se kreslilo. Kostky na stavění. Knížka s obrázky. Sáňky, které jedou rychle z kopce. A ještě srdíčko, protože bez srdíčka to není pořádný dopis.` },
        { t: `A úplně dole ${n('plyšové zvířátko, to nejmilejší', 'plyšová zvířátka, ta nejmilejší')} ze všech: ${c.animal}.` },
        { t: `Dopis se složil napůl, ještě jednou napůl a položil se za okno. Tak se to dělá odjakživa. Jak si ho Ježíšek vyzvedne, to nikdo neví. To je tajemství a tak to má zůstat.` },
        { t: `V noci se zvedl vítr. Okno zadrnčelo, v komíně zahvízdalo a pak to venku znělo, jako by si někdo pořádně kýchl.`, sfx: 'wind' },
        { t: `${c.H} se ${g('probudil', 'probudila', 'probudili')} a ${g('došel', 'došla', 'došli')} k oknu.` },
        { t: `Dopis za oknem nebyl. Místo něj tam seděl malý sněhový vír. Točil se dokola jako káča, měl dvě oči z jinovatky a z očí mu kapaly drobné ledové slzičky. Cink, cink, padaly na parapet.` },
        { t: `Okno se pootevřelo jen na škvírku, aby do pokoje nenapadal sníh.` },
        { t: `„Já jsem Vichřík,“ popotáhl vír. „Nejmladší vítr z Ježíškovy pošty. Letos poprvé nosím dopisy z vašich ulic nahoru do mraků. A hned napoprvé jsem to pokazil.“` },
        { t: `„Měl jsem plný pytel dopisů. A pak mi do nosu vlétla vločka a já kýchl. Pořádně, větrně, na celé okolí. Dopisy se rozletěly na všechny strany. Na střechy, do stromů, do závějí.“` },
        { t: `Vichřík vytáhl z kapsy jeden mokrý dopis. Sníh na něm rozmazal písmenka a ze jména zbyla jen modrá šmouha. „Musím je všechny donést do rána. Jenže když Ježíšek neví, od koho dopis je, neví ani, kam má zazvonit.“` },
        { t: `„${n('Pomůžeš', 'Pomůžete')} mi?“` },
        { t: `${c.H} ${g('kývl', 'kývla', 'kývli')}.` },
        { t: `Bunda přes pyžamo, čepice, šála dvakrát kolem krku. A rukavice, protože na mráz se nechodí s holýma rukama, ani když je to kouzelný mráz.` },
        { t: `Vichřík se zatočil, zavířil a najednou bylo pod nohama měkko jako na peřině. Letělo se nad zahradou, nad komíny, nad střechami.`, sfx: 'magic' },
        { t: `Všechno dole spalo. Vánoční světýlka v oknech blikala jako hvězdičky, které spadly dolů a nechtělo se jim zpátky.` },
        { t: `Na náměstí stál velký vánoční strom. Vichřík ho cestou trochu pocuchal, jen tak z radosti, a hvězda na špičce se zhoupla a zase narovnala.` },
        { t: `Tak takhle to vypadá ${c.inTown}, když se člověk dívá shora.` },
        { t: `„Kam ty dopisy vlastně nosíš?“ „Nahoru, na Ježíškovu poštu,“ zahvízdal Vichřík. „Kdo je tam třídí, to ${n('ti', 'vám')} neprozradím. To je tajemství i pro vítr. Já je jen nosím.“` },
        { t: `„Jen jedno pravidlo,“ zafoukal Vichřík. „Cizí dopisy se nečtou. Dneska smíme udělat výjimku, ale jen kvůli doručení. Přečteme jen tolik, abychom poznali, čí dopis je. A co se dozvíme, zůstane mezi námi.“` },
        { t: `„${n('Slibuju', 'Slibujeme')}.“` },
        { t: `První dopis trčel z komína na náměstí. Byl celý od mouky a voněl vanilkou a máslem.` },
        { t: `Stálo v něm: „Milý Ježíšku, přál bych si, aby mi letos aspoň jednou vyšly vanilkové rohlíčky a ani jeden se nezlomil. Každý rok se mi jich polovina rozdrobí.“ Podpis byl rozmazaný.` },
        { t: `Mouka, vanilka, rohlíčky. Kdo jen to může být? Dole na náměstí svítilo jediné okno. Za ním se něco hnětlo, válelo a sypalo.` },
        { t: `„Pekárna!“ ${g('vyhrkl', 'vyhrkla', 'vyhrkli')} ${c.H}.` },
        { t: `Pekaři totiž vstávají, když ostatní ještě spí, aby byly ráno rohlíky čerstvé. Na obálku se tužkou připsalo: Z pekárny na náměstí. A Vichřík zavýskal, až se z komína vyvalil obláček.` },
        { t: `Druhý dopis visel na větvi staré lípy. Písmena v něm byla veliká a křivá a v rohu byla otištěná malá tlapka.` },
        { t: `„Milý Ježíšku, prosím nový míček pro Punťu. Ten starý mu spadl do potoka a on je z toho celý smutný. Pro mě nic nepotřebuju, jen ten míček.“` },
        { t: `Pod lípou stála psí bouda a na ní cedulka. Vichřík na ni posvítil jiskřičkou mrazu. PUNŤA, stálo tam. Z boudy se ozvalo ospalé „haf“ a vykoukl černý čumák.` },
        { t: `Takže tenhle dopis psala Punťova kamarádka. A přála si dárek, který vůbec nebyl pro ni.` },
        { t: `${c.H} se nad tím ${g('zamyslel', 'zamyslela', 'zamysleli')}.` },
        { t: `Třetí dopis ležel v závěji u plotu. Nebylo v něm ani jedno písmenko. Jen obrázek: velký kulatý sněhulák s mrkví a vedle něj malinký človíček, který se na něj usmívá.` },
        { t: `„Tohle psal někdo, kdo ještě neumí písmenka,“ řekl Vichřík. „Ale kdo?“` },
        { t: `Za plotem stál dům. ${c.H} ${g('ukázal', 'ukázala', 'ukázali')} na schody.` },
        { t: `Na schodech u dveří stály malinké holínky, tak malé, že by se vešly do dlaně, a vedle nich sáňky s opěrátkem. A uprostřed zahrady ležela jedna sněhová koule. Jen jedna. Na druhou už asi nestačily síly.` },
        { t: `Na obálku se připsalo: Od malých holínek. A do hlavy se k tomu přidala ještě jedna tajná poznámka: zítra pomoct s druhou koulí.` },
        { t: `Cestou k dalšímu dopisu se ozvalo krákání. Na plotě seděla vrána a v zobáku držela obálku posypanou třpytkami. Třpytky se leskly v měsíčním světle a vrána se tvářila, že je to její poklad.` },
        { t: `„Vrať to, to je dopis pro Ježíška!“ zafučel Vichřík. Vrána jen pevněji sevřela zobák. Kdo by se vzdával něčeho tak lesklého?` },
        { t: `${c.H} ${g('sáhl', 'sáhla', 'sáhli')} do ${n('kapsy', 'kapes')}.` },
        { t: `Tam něco zašustilo. Stříbrný papírek od bonbonu, uhlazený a schovaný, protože byl moc hezký na vyhození.` },
        { t: `Papírek se položil na plot. Vrána koukla na papírek, pak na dopis, pak zase na papírek. Nakonec pustila obálku, papírek si odnesla do hnízda a cestou spokojeně zakrákala. Asi to znamenalo děkuju.` },
        { t: `Ve třpytivém dopise si dvojčata přála sáňkovou dráhu pro celou ulici. Na obálku se připsalo: Od dvojčat z modrého domu. Modrý dům byl v ulici jen jeden, ten se splést nedal.` },
        { t: `Čtvrtý dopis odfoukl vítr nejdál. ${far}` },
        { t: `Byl napsaný úhledným, trochu roztřeseným písmem, takovým, jakým se píšou přáníčka k svátku. Jméno na něm zůstalo celé. Vlasta.` },
        { t: `„Milý Ježíšku, já už nic nepotřebuju. Mám teplá kamna, mám čaj a mám kocoura Mourka. Jen bych byla ráda, kdyby se u mě letos někdo zastavil a chvíli si se mnou povídal. Vnoučata bydlí daleko a večery jsou u mě moc tiché.“` },
        { t: `Paní Vlasta! Ta, co bydlí na konci ulice a každé ráno mává z okna na všechny, kdo jdou kolem.` },
        { t: `${c.H} dlouho ${g('mlčel', 'mlčela', 'mlčeli')}.` },
        { t: `Tohle přání bylo jiné než ostatní. Na tohle Ježíšek nepotřeboval dílnu ani sáně. Tohle mohl splnit kdokoli, kdo má dvě nohy a chvilku času.` },
        { t: `„Ten dopis poneseme taky. Ale tohle přání si ${n('vezmu na starost já', 'vezmeme na starost my')}.“ Vichřík se zatočil tak radostně, že z něj pršely třpytky.`, sfx: 'sparkle' },
        { t: `Poslední dopis našli úplně nahoře. Zachytil se kohoutovi na kostelní věži za ocas.` },
        { t: `${c.H} ${g('poznal', 'poznala', 'poznali')} ten dopis hned.` },
        { t: `Kostky, knížka, sáňky, srdíčko. Byl to ten dopis, který večer ležel za oknem. Všechno v něm byly pěkné věci. Jenže vedle dopisů od pekaře, od Punťovy kamarádky a od paní Vlasty vypadal najednou nějak osaměle. Byly v něm jen věci pro sebe.` },
        { t: `Vichřík půjčil tužku a na konec dopisu se připsalo ještě pár řádků: „A prosím, ať má Punťa nový míček. Ať se pekaři povedou rohlíčky. Ať ten malý postaví sněhuláka. A za paní Vlastou ${n('přijdu já', 'přijdeme my')}.“`, sfx: 'paper' },
        { t: `Pak už byl pytel plný. Vichřík se nadechl, nafoukl tváře a vyletěl s ním vysoko, až k mrakům.` },
        { t: `Nahoře mezi mraky na chvilku zazářilo teplé zlaté světlo a tichounce cinkl zvoneček. Víc vidět nebylo. Ježíška ještě nikdy nikdo neviděl. A tak je to správně.`, sfx: 'ding' },
        { t: `Cesta domů byla měkká a ospalá. Postel byla ještě teplá a polštář voněl jako vždycky. A ráno ležela na parapetu jen malá hromádka sněhu. Měla tvar úsměvu.` },
        { t: `U snídaně se o dopisech nemluvilo. Slib je slib. Jen jedna otázka se udržet nedala: „Kdy půjdeme za paní Vlastou?“` },
        { t: `V dalších dnech se toho dělo hodně.` },
        { t: `U plotu s malými holínkami se stavěl sněhulák. Malý človíček se jmenoval Tadeášek, byly mu dva roky a koulel sníh tak vážně, jako by stavěl hrad. Druhá koule, třetí koule, mrkev a dva kamínky na oči. Tadeáškova maminka přinesla místo klobouku starý hrnec a sněhulák vypadal jako kuchař. Tadeášek výskal, až na sousední střeše vyletěli vrabci.` },
        { t: `A v sobotu se zazvonilo u paní Vlasty. S ${p.ins} a s krabičkou cukroví.` },
        { t: `Paní Vlasta otevřela dveře a chvíli nevěřila. Pak se jí rozsvítily oči, tak jako se rozsvítí stromeček, když se zapojí světýlka.` },
        { t: `„To je ale vzácná návštěva! Pojďte dál, ${c.h.voc}, ať nenastydnete.“` },
        { t: `Pil se čaj ze šálků s růžičkami a kocour Mourek si vybral klín návštěvy a předl jako motorek. Paní Vlasta vyprávěla, jak se slavily Vánoce, když byla malá. Jak se kapr koupal ve vaně a jak se pouštěly lodičky z ořechových skořápek se svíčkou uvnitř.` },
        { t: `A jak jednou na Štědrý den napadlo tolik sněhu, že se z domu nedalo vyjít dveřmi, a její tatínek musel ven oknem. Smálo se tolik, že se kocour urazil a odešel na kamna.` },
        { t: `Pak vytáhla krabici se starými ozdobami. Skleněné ptáčky s opravdovými pírky na ocáscích, stříbrné zvonečky a jednu baňku, které bylo přes sto let. „Tu pověsím až úplně nahoru,“ řekla. „Ať na všechny dobře vidí.“` },
        { t: `Když se odcházelo, paní Vlasta stála ve dveřích a ještě dlouho mávala. „Tohle je ten nejhezčí dárek, jaký jsem letos dostala,“ řekla. „A to ještě ani nejsou Vánoce.“` },
        { t: `Cestou domů bylo uvnitř zvláštně teplo. Úplně stejně, jako když se rozbaluje dárek. Možná ještě trochu víc.` },
        { t: `A od té doby se každé ráno cestou kolem konce ulice mávalo nahoru do okna. A z okna se mávalo zpátky.` },
        { t: `Na Štědrý den se čekalo od rána. Čekání bylo dlouhé jako celý prosinec. Na stromečku svítila světýlka, z kuchyně voněla vánočka a ručičky hodin se skoro nehýbaly.` },
        { t: `Večer, když venku byla tma a na stole voněla večeře, cinkl zvoneček. Pod stromečkem ležely dárky. Jaké, to zůstane tajemstvím. Ale jedno je jisté: Ježíšek věděl přesně, kam má zazvonit.` },
        { t: `A druhý den? Punťa běhal po zahradě s novým červeným míčkem. Na dveřích pekárny visel papír: „Letos ani jeden zlomený!“ Dvojčata z modrého domu stavěla s půlkou ulice sáňkovou dráhu. A z okna na konci ulice mávala paní Vlasta. Na čaj si tentokrát pozvala i sousedy z vedlejšího domu.` },
        { t: `Večer zafoukal do okna malý vítr. Krátce a vesele, jako když si někdo píská. Vichřík. Letos už nekýchl ani jednou.`, sfx: 'wind' },
        { t: `Dobrou noc, ${c.h.voc}. A veselé Vánoce.`, pause: 3 },
      ];
    },
  },
  {
    id: 'certik-bez-strachu',
    delka: 10,
    pro: 'm',
    pozn: 'Mikulášský večer. Nejmenší čertík Fik se celý rok učí strašit, ale místo „Bububu!“ mu vždycky vyletí „Bu… bu… BUCHTIČKY!“ a všichni se smějí. U hrdiny doma právě jeho smích rozpustí strach, takže se vrátí zapomenutá básnička. Hrdina pak Fikovi poradí, ať u sousedů nestraší, ale rozesměje vyděšenou Natálku. Mikuláš z něj udělá Čertíka Rozesmívače.',
    pouceni: 'Je dobré být sám sebou a strach nikoho nic dobrého nenaučí, smích otevírá dveře i pusu.',
    free: false,
    cats: ['svatky', 'sranda'],
    ages: [3, 8],
    mood: 'adventure',
    cover: { emoji: '😈', g1: '#b71c1c', g2: '#ffcc80' },
    title: () => `Čertík, který neuměl strašit`,
    text: (c) => {
      const g = c.g, n = c.n, p = c.p1;
      return [
        { t: `${c.H} ${g('přitiskl', 'přitiskla', 'přitiskli')} nos na okno.` },
        { t: `Venku je tma, padá sníh a dneska večer přijde Mikuláš!` },
        { t: `Každý rok pátého prosince večer, když se snáší tma a v oknech se rozsvěcují lampičky, chodí od domu k domu Mikuláš. S bílým vousem, se zlatou berlou a s velkou knihou pod paží. Vedle něj kráčí anděl, celý v bílém. A za nimi dupou čerti.` },
        { t: `Letos s nimi poprvé šel i čertík Fik. Byl ze všech čertů nejmenší. Rožky měl jako dva žaludy, ocásek stočený do otazníku a kožíšek tak chlupatý, že vypadal jako rozčepýřený kartáč na boty.` },
        { t: `Celý rok se Fik učil strašit. Učil ho starý čert Bručoun, který měl vousy až po kolena a hlas jako hrom v prázdném sudu.` },
        { t: `„Pořádný čert musí umět tři věci,“ bručel Bručoun. „Zachrastit řetězem. Zadupat kopytem. A zařvat: Bububu!“` },
        { t: `Fik zachrastil. Jenže řetěz měl z kancelářských sponek, a tak to jen tenounce cinklo. Fik zadupal. Jenže kopýtka měl tak malá, že to znělo jako ťapání kotěte. A pak se nadechl až do špiček rožků a zařval:` },
        { t: `„Bu… bu… BUCHTIČKY!“` },
        { t: `Bručounovi se zatřásly vousy. Pak se zatřásl celý. A pak se smál tak, že spadl z pařezu.` },
        { t: `Fik to zkoušel dál. Strašil sovu. „Bu… bu… BUBLIFUK!“ Sova se smála, až jí z hnízda vypadla dvě pírka. Strašil ježka. „Bu… bu… BUDÍK!“ Ježek se smál, až se mu bodlinky zježily na všechny strany. Strašil i svůj obraz v kaluži. Ten se smál nejvíc.`, sfx: 'owl' },
        { t: `Nakonec šel strašit i strašáka na poli. „Bu… bu… BRAMBORÁK!“ Strašák se nezasmál, protože strašáci se smát neumějí. Ale vrány, které mu seděly na klobouku, se smály tak, že popadaly do brázdy.` },
        { t: `„Já to nikdy neumím,“ fňukal Fik. „Čert, který neumí strašit, je k ničemu.“` },
        { t: `Mikuláš ho pohladil mezi rožky. „To se teprve uvidí. Pojď dnes s námi.“` },
        { t: `A tak šli. Ze zasněženého lesa dolů k vesnicím a městům. Mikuláš vpředu, anděl s lucernou vedle něj, Bručoun s řetězem a úplně vzadu Fik. Cinkal sponkami a cestou si potichu zkoušel: bu… bu… bu…` },
        { t: `U ${c.h.gen} doma se ten večer nikdo nemohl dočkat.` },
        { t: `Básnička byla naučená, stůl uklizený a za oknem byla tma jako v pytli. Uši poslouchaly každé zavrzání. A pak: bum, bum, bum. Někdo zaklepal na dveře.` },
        { t: `Ve dveřích stál Mikuláš. Velký, laskavý, s vousem bílým jako sníh na plotě. Anděl se usmíval a v ruce mu zvonil zvoneček.`, sfx: 'ding' },
        { t: `A za nimi se dovnitř protlačil Bručoun. Zachrastil řetězem, až to zadrnčelo v oknech. Zadupal, až poskočily hrnky na poličce. Zakoulel očima a zavrčel.` },
        { t: `${c.H} ${g('couvl', 'couvla', 'couvli')} za ${p.acc}.` },
        { t: `V bříšku se stáhl studený uzlík. A básnička? Ta se schovala tak hluboko, že nebylo vidět ani první slovo. Strach to tak dělá. Zamkne pusu a klíček schová.` },
        { t: `„Tak copak,“ zeptal se laskavě Mikuláš. „${n('Umíš', 'Umíte')} nám říct básničku?“ Ticho. Jenom hodiny tikaly.` },
        { t: `Vtom se mezi Bručounovýma nohama prosmýkl Fik. Chtěl taky strašit, když už je tady. Nadechl se, zamračil se, roztáhl drápky a…` },
        { t: `„Bu… bu… BUCHTIČKY S MÁKEM!“` },
        { t: `Šlápl si přitom na vlastní ocásek, udělal kotrmelec a skutálel se pod stůl. Ven mu koukaly jen dvě kopýtka a rožky měl zamotané do ubrusu.` },
        { t: `A ${c.H} se ${g('rozesmál', 'rozesmála', 'rozesmáli')}.` },
        { t: `Nejdřív jen trošku, pak víc a nakonec tak, že se to nedalo zastavit. A jak se smích rozléval, studený uzlík v bříšku se rozvazoval. Klíček od pusy vyskočil. A básnička vyšla ven úplně sama.` },
        { t: `„Bílý vous a teplý kabát, Mikuláš k nám chodí rád. Anděl zpívá, čertík skáče, dneska nikdo nepláče!“` },
        { t: `„To je krásná básnička,“ řekl Mikuláš. Pak otevřel velkou knihu a nalistoval správnou stránku. „Tady se píše, že ${n('jsi', 'jste')} letos ${g('pomáhal', 'pomáhala', 'pomáhali')} s nákupem. A že ${n('ses', 'jste se')} ${g('rozdělil', 'rozdělila', 'rozdělili')} o poslední sušenku.“` },
        { t: `Pak se podíval přes brýle. „A taky se tu píše, že se někdy nechce uklízet hračky.“ Chvilku bylo ticho. „Ale to se nechce ani mně,“ zašeptal Mikuláš a mrkl.` },
        { t: `Nakonec knihu zaklapl a z pytle vytáhl balíček. Mandarinka, ořechy, malý čokoládový Mikuláš a perníček ve tvaru čertíka s ocáskem jako otazník.`, sfx: 'sparkle' },
        { t: `Jenže když se zavíraly dveře, sedl si Fik venku na schod a smutně kreslil ocáskem do sněhu. „Zase jsem nikoho nevystrašil,“ šeptal. „Zase jsem všechno pokazil.“` },
        { t: `${c.H} ${g('vyklouzl', 'vyklouzla', 'vyklouzli')} ven za ním.` },
        { t: `${cap(p.nom)} ${p.g('zůstal', 'zůstala')} stát ve dveřích. Na schody odtamtud padalo teplé světlo.` },
        { t: `„Ty jsi nic nepokazil. ${n('Já jsem', 'My jsme')} se ${g('bál', 'bála', 'báli')} a básnička se ${n('mi', 'nám')} schovala. A pak ${n('jsi mě', 'jsi nás')} rozesmál a ona se vrátila.“` },
        { t: `Fik zvedl hlavu. „Opravdu?“ Ale hned zase svěsil uši. „Jenže čert má strašit. To se ví odjakživa.“` },
        { t: `Mikuláš mezitím zaklepal u sousedů. A za chvilku se odtamtud ozval pláč. Takový ten velký, kulatý pláč, který se nedá utišit. Dveře u sousedů zůstaly pootevřené, a tak bylo všechno vidět až na schody.` },
        { t: `Malá Natálka, které byly teprve dva roky, se schovala mamince pod svetr a ven koukaly jen bačkůrky. Bručoun se snažil vrčet potichu, ale bylo to ještě horší. Znělo to jako lednička, která se zlobí.` },
        { t: `Mikuláš se bezradně podíval na anděla. Anděl se bezradně podíval na Mikuláše.` },
        { t: `${c.H} ${g('chytil', 'chytila', 'chytili')} Fika za ocásek.` },
        { t: `„Nestrašit,“ ${g('zašeptal', 'zašeptala', 'zašeptali')} mu do ucha. „Udělej to, co umíš nejlíp. Rozesměj ji.“` },
        { t: `Fik se nadechl. Vešel do obýváku, uklonil se Natálce až k zemi a…` },
        { t: `„Bu… bu… BUBLINKY!“ A opravdu: vytáhl z kapsy bublifuk a foukl. Celý obývák se zaplnil duhovými bublinami.` },
        { t: `Pak udělal kotrmelec, ocásek se mu zavázal na mašličku a jedna bublina mu přistála přímo na nose. Plop!` },
        { t: `Pláč se zastavil. Zpod svetru vykoukl nos. Pak oko. Pak celá Natálka. A pak se zasmála: „Čeltík! Bubliny!“` },
        { t: `A jak se smála, tak taky zazpívala. Písničku o sněhulákovi, celou od začátku do konce, i když půlku slov si vymyslela.` },
        { t: `Mikuláš si pohladil vous. „Strachem se ještě nikdo nic dobrého nenaučil,“ řekl tiše. „Smíchem se otvírají dveře. I ty nejmenší pusinky.“` },
        { t: `A pak Fika slavnostně jmenoval. „Od dnešního dne jsi Čertík Rozesmívač. Budeš chodit do každého domu první, aby se nikdo nebál a každý si vzpomněl na svou básničku.“`, sfx: 'magic' },
        { t: `Bručoun se poškrábal ve vousech. „A já? Já se mám jako učit rozesmívat?“ Zkusil to hned. Nadechl se a zahřměl: „Bu… bu… BUŘTY!“` },
        { t: `Smáli se všichni. Natálka, její maminka, anděl i Mikuláš, až se mu kniha pod paží roztřásla. A nejvíc se smál Fik.` },
        { t: `Večer, už v posteli, bylo ještě dlouho slyšet zvenku zvoneček, cinkání sponek a vzdálený smích. To šel Mikuláš dál, od domu k domu. A do každého domu vešel jako první malý čertík s ocáskem jako otazník.` },
        { t: `${c.H} ${g('zavřel', 'zavřela', 'zavřeli')} oči a ${g('usmíval', 'usmívala', 'usmívali')} se.` },
        { t: `Ráno ležel na parapetu malý řetízek z kancelářských sponek. A v něm zastrčený papírek, na kterém bylo křivým čertím písmem napsáno: Bu… bu… DĚKUJU!`, sfx: 'paper' },
        { t: `Ten papírek visí nad postelí dodnes. A kdyby se ${n('ti', 'vám')} někdy v bříšku stáhl studený uzlík, stačí si potichu říct to kouzelné slovo. Bu… bu… buchtičky!` },
      ];
    },
  },
  {
    id: 'zajicek-malir',
    delka: 10,
    pro: 'f',
    pozn: 'Před Velikonocemi nestíhá zajíček Kropánek malovat kraslice, protože každou kaňku smyje a začne znovu. Hrdina mu pomáhá. Když mu samotnému ukápne kaňka, udělá z ní berušku, a Kropánek objeví, že kaňka může být začátek. Spolu barví vajíčka v cibulových slupkách s lístkem (musí se počkat) a každé je jiné. Bez pomlázky.',
    pouceni: 'Krásné věci potřebují trpělivost a vlastní práce nemusí být dokonalá, aby z ní byla radost.',
    free: false,
    cats: ['svatky', 'zvirata'],
    ages: [2, 7],
    mood: 'lullaby',
    cover: { emoji: '🐰', g1: '#aed581', g2: '#fff59d' },
    title: () => `Zajíček malíř`,
    text: (c) => {
      const g = c.g, n = c.n, p = c.p1;
      return [
        { t: `Jaro přišlo po špičkách. Nejdřív vystrčily hlavičky sněženky, pak se na vrbě objevily chlupaté kočičky a nakonec se na střeše ozval kos, jako by zvonil na budíček.`, sfx: 'birds' },
        { t: `A když se blíží Velikonoce, má jeden malý zajíček nejvíc práce z celého roku.` },
        { t: `Jmenuje se Kropánek. Má hnědý kožíšek, ocásek jako chomáček vaty a na uších drobné tečky, jako by ho někdo pokropil barvou. Bydlí v norce pod starým šeříkem. Má štětečky z vlastních chloupků, misky ze žaludových čepiček a barvy z jahod, borůvek a pampelišek. A maluje kraslice.` },
        { t: `Vajíčka mu nosí slepičky ze sousedního dvora. Vajíčka totiž snášejí slepice, ne zajíci. Zato malovat je neumí nikdo tak pěkně jako Kropánek.` },
        { t: `Toho večera ${g('uviděl', 'uviděla', 'uviděli')} ${c.H} z okna něco zvláštního.` },
        { t: `Pod šeříkem seděl zajíček a kolem něj stály košíky. Plné vajíček. Bílých, úplně holých, bez jediné barvičky. Jen jedno jediné bylo hotové, modré s bílými vlnkami. A zajíček nad ním vzdychal tak hluboko, až se mu klepaly vousky.` },
        { t: `${cap(p.nom)} ${p.g('dovolil', 'dovolila')} vyběhnout na zahradu.` },
        { t: `Jen na chvilku, v holínkách a s bundou přes ramena.` },
        { t: `„Ahoj. Proč tak vzdycháš?“` },
        { t: `„Zítra jsou Velikonoce,“ povzdechl si zajíček. „Do rána musím pomalovat všechna tahle vajíčka. Všechna stejně krásná, stejně hladká, bez jediné kaňky. A já mám od rána hotové jen jedno.“` },
        { t: `„A proč musí být všechna stejná?“ Kropánek zamrkal. „No… protože… protože se to tak má. Co kdyby někdo našel vajíčko s kaňkou? To by byla ostuda na celou louku.“` },
        { t: `Pak ukázal, jak to dělá. Namočil štěteček, opatrně táhl modrou čáru… a na jejím konci se udělala malinká tečka. Tak malá, že by ji neviděla ani beruška s brýlemi.` },
        { t: `„Kaňka!“ zašeptal Kropánek zděšeně. Vzal hadřík, všechno smyl a začal znovu.` },
        { t: `Ťup, ťup, štěteček. Čára. Kaňka. Hadřík. A znovu. Ťup, ťup, štěteček. Čára. Kaňka. Hadřík.` },
        { t: `„Takhle to nestihneš ani do příštích Velikonoc,“ ${g('řekl', 'řekla', 'řekli')} ${c.H}.` },
        { t: `„${n('Můžu', 'Můžeme')} ti pomoct?“` },
        { t: `Kropánek si nervózně olízl tlapku. „A co když ${n('uděláš', 'uděláte')} kaňku?“` },
        { t: `„Tak ji ${n('udělám', 'uděláme')}.“` },
        { t: `Kropánek podal štěteček a misku s červenou barvou. Vajíčko bylo uvařené natvrdo, ještě trochu teplé a krásně kulaté.` },
        { t: `${c.H} ${g('začal', 'začala', 'začali')} malovat kytičku.` },
        { t: `Stonek se povedl. Jeden lísteček se povedl. A pak plác! Ze štětečku skápla velká, kulatá, červená kaňka. Přímo doprostřed.` },
        { t: `Kropánek vyjekl a natáhl tlapku pro hadřík.` },
        { t: `„Počkej!“ ${g('vykřikl', 'vykřikla', 'vykřikli')} ${c.H}.` },
        { t: `Kaňka byla kulatá. Červená. A něco připomínala. Stačilo přidat černou hlavičku. Šest tenkých nožiček. A tečky. Jedna, dvě, tři, čtyři, pět, šest, sedm.` },
        { t: `Na vajíčku seděla beruška sedmitečná a vypadala, že každou chvíli roztáhne křídla a odletí.`, sfx: 'sparkle' },
        { t: `Kaňka, která chtěla všechno zkazit, se proměnila v to nejhezčí na celém vajíčku.` },
        { t: `Kropánek zůstal stát s hadříkem v tlapce. Dlouho koukal. Pak řekl potichu: „Ona je hezčí než moje modré.“` },
        { t: `A pak si zamumlal sám pro sebe: „Kaňka není konec. Kaňka je… začátek!“` },
        { t: `Vzal štěteček a maloval. A když mu ukápla žlutá kapka, nesáhl po hadříku. Udělal z ní kuřátko. Zelená kapka se proměnila v žabičku, modrá šmouha v mráček a jedna úplně nepovedená čára v ocásek pro myšku.` },
        { t: `Pak se míchaly barvy. Žlutá s modrou udělaly zelenou jako jarní tráva. Červená se žlutou oranžovou jako mrkev. A když se smíchalo úplně všechno, vyšla hnědá jako bláto. „I to se hodí,“ prohlásil Kropánek. „Na ježka.“` },
        { t: `Další vajíčko dostalo pruhy. Měly být rovné, ale vyšly jako vlnky na rybníce. Kropánek je chvíli zkoumal a pak řekl: „Tohle vajíčko plave.“ A domaloval mu rybičku.` },
        { t: `Pak přišla na řadu cibulová vajíčka. Kropánek měl nad ohníčkem hrnec s vodou a cibulovými slupkami. Voda v něm byla hnědá jako čaj.` },
        { t: `„Na vajíčko se přiloží lísteček,“ vysvětloval Kropánek. „Třeba jetel nebo petrželka. Pak se pevně zabalí do kousku punčochy, zaváže se a ponoří do hrnce.“ Na horký hrnec sahal jen on. Tohle je práce pro velké tlapky.` },
        { t: `A pak se čekalo.` },
        { t: `${c.H} ${g('nevydržel', 'nevydržela', 'nevydrželi')} a ${g('nakoukl', 'nakoukla', 'nakoukli')} do hrnce.` },
        { t: `„Už?“ „Ještě ne.“ Za chvilku znovu: „Už?“ „Ještě ne. Barva potřebuje čas. Stejně jako jaro.“` },
        { t: `Tak se počítaly hvězdy, které se rozsvěcovaly nad zahradou. Jedna, dvě, deset, dvacet. Kropánek mezitím pomaloval dvacet vajíček a ani jedno nesmyl.` },
        { t: `Z rybníka za zahradou se ozvalo první jarní kuňkání. Kuňk. Kuňk, kuňk. Žáby se probudily ze zimního spaní a zkoušely, jestli jim ještě funguje hlas.` },
        { t: `Konečně! Vajíčko vyjelo z hrnce, punčoška se rozvázala a lísteček odpadl. A tam, kde ležel, zůstal na hnědočerveném vajíčku světlý obrázek jetelového lístku. Každá žilka, každý obloučeček. Jako by ho tam někdo nakreslil tím nejtenčím perem.`, sfx: 'magic' },
        { t: `„Kdybychom ho vytáhli hned, bylo by sotva nažloutlé,“ zašeptal Kropánek. „Některé krásné věci se nedají uspěchat.“` },
        { t: `Na ${n('poslední vajíčko se malovalo zvíře, které má', 'poslední vajíčka se malovala zvířata, která mají')} ${c.H} ze všech nejradši: ${c.animal}.` },
        { t: `Ocásek se trochu nepovedl a jedno ucho bylo větší než druhé. Ale zato se ${n('to zvíře usmívalo', 'ta zvířata usmívala')}. A na úsměv se každý podívá nejdřív.` },
        { t: `Za chvíli byly košíky plné. Pruhovaná vajíčka a tečkovaná. Vajíčka s lístky a s kuřátky. Jedno kostkované, jedno s mráčkem, jedno se žabičkou. Ani dvě nebyla stejná.` },
        { t: `„Tohle jsou nejkrásnější kraslice, jaké jsem kdy maloval,“ řekl Kropánek a vousky mu trčely do všech stran. „Každá je jiná. Úplně jako děti.“` },
        { t: `Z okna se ozvalo volání. To ${p.nom} ${p.g('volal', 'volala')}, že je čas jít spát.` },
        { t: `„Ještě jedno!“ A pak ještě jedno. A pak už opravdu poslední. A pak ještě jedno úplně maličké, ale to se nepočítá.` },
        { t: `Kropánek podal na rozloučenou vajíčko s beruškou. „Tohle je ${n('tvoje', 'vaše')}. To první, s kaňkou.“` },
        { t: `Večer v posteli voněly prsty ještě trochu barvou a cibulí. Beruška seděla na nočním stolku a hlídala.` },
        { t: `${c.H} ${g('usnul', 'usnula', 'usnuli')} skoro hned.` },
        { t: `A v noci, když celý svět spal, se zahradami plížil malý zajíček s tečkovanýma ušima. Do trávy, pod keře a za konve schovával kraslice, každou jinou.` },
        { t: `Až do posledního domu ${c.inTown}.` },
        { t: `Ráno děti hledaly v trávě a jedna přes druhou volaly: „Já mám pruhované! Já mám s žabičkou! A já s mráčkem!“ Nikdo neměl stejné jako ten druhý. A nikoho to nemrzelo.` },
        { t: `Jeden kluk našel vajíčko s rybičkou v konvi na zalévání. Jedna holčička objevila ježka v bačkoře u dveří. Tedy vajíčko s ježkem. Jak se tam dostalo, to ví jen Kropánek.` },
        { t: `Pod šeříkem, na úplně čestném místě, ležela ještě jedna kraslice. Modrá, s bílými vlnkami. Na konci jedné vlnky měla malinkou tečku. Tu tečku Kropánek tentokrát nesmyl. Udělal z ní sluníčko.` },
        { t: `A Kropánek? Ten spí pod šeříkem, tlapky má barevné až po lokty a zdají se mu samé kaňky. Ty nejkrásnější.` },
        { t: `Dobrou noc, Kropánku. Dobrou noc, ${c.h.voc}.`, pause: 3 },
      ];
    },
  },
  {
    id: 'lampionovy-pruvod',
    delka: 5,
    pro: 'vse',
    pozn: 'Podzimní lampionový průvod. Vítr sfoukne lampion malé Bětce a hrdina se zastaví a nechá jí připálit od svého (špejli drží dospělý). Jeho světlo se nezmenší a světlo pak putuje od lampionu k lampionu až k rybníku. Klidný návrat domů a usínání.',
    pouceni: 'Světlo, o které se rozdělíš, se nezmenší, a když se zastavíš pro druhého, nikdo nezůstane ve tmě.',
    free: false,
    cats: ['svatky', 'noc'],
    ages: [2, 6],
    mood: 'lullaby',
    cover: { emoji: '🏮', g1: '#283593', g2: '#ffb74d' },
    title: () => `Lampionový průvod`,
    text: (c) => {
      const g = c.g, n = c.n, p = c.p1;
      return [
        { t: `Na podzim se stmívá brzy. Sotva se dojí svačina, už se venku rozsvěcují lampy a pod nohama šustí listí.` },
        { t: `Dnes ale nikdo nejde spát hned po večeři. Dnes je lampionový průvod!` },
        { t: `${c.H} ${n('nese lampion kulatý', 'nesou lampiony kulaté')} jako měsíc.` },
        { t: `Uvnitř stojí malá svíčka a zapálit ji smí jen dospělý.` },
        { t: `${cap(p.nom)} ${p.g('škrtl', 'škrtla')} sirkou.` },
        { t: `Fff! A ${n('měsíc se rozsvítil', 'měsíce se rozsvítily')}. Oranžově, teple, jako hrnek kakaa.` },
        { t: `Takový průvod ${c.inTown} ještě nebyl!` },
        { t: `Vpředu šel pán s bubínkem a všichni zpívali: „Svítí, svítí lampička, malá jako jablíčko. Tma je velká, my jsme malí, ale světla jsme si vzali.“` },
        { t: `Svítila ryba. Svítila sova. Svítila hvězda, dýně a jedna žirafa s dlouhým krkem. Jedno světýlko, dvě světýlka, sto světýlek. Celá ulice se houpala ve světle.` },
        { t: `Pod nohama šustilo listí, šusty, šusty. Z chodníku se kutálely kaštany. A na zídce seděla kočka, koukala do světel a oči jí svítily jako dva malinké lampiony.` },
        { t: `A pak se zvedl vítr. Fíí! Prohnal se ulicí, zavířil listím a sfoukl jedno světýlko.`, sfx: 'wind' },
        { t: `Byla to papírová rybka. Patřila malé Bětce s červenou čepicí. Bětka stála uprostřed chodníku, rybka jí visela ve tmě a z oka jí ukápla slza. Bětce, ne rybce.` },
        { t: `Průvod šel dál. Nikdo si ničeho nevšiml, Bětka byla tak malá a rybka tak tmavá. Světla se vzdalovala.` },
        { t: `${c.H} se ${g('zastavil', 'zastavila', 'zastavili')}.` },
        { t: `Malá myšlenka zašeptala: „Když jí dám ze svého světla, nebude ho pak míň?“ Svíčka v měsíci tiše blikala. A Bětka tam stála tak sama.` },
        { t: `„Můžeme jí připálit?“ ${g('zeptal se', 'zeptala se', 'zeptali se')} ${c.H}.` },
        { t: `Z kapsy se vytáhla dlouhá špejle. Velká ruka ji opatrně nahnula ke svíčce v měsíci. Špejle chytila plamínek, přenesla ho k rybce a…` },
        { t: `Blik! Rybka se rozsvítila. Bětka se usmála od ucha k uchu.`, sfx: 'sparkle' },
        { t: `A měsíc? Ten svítil úplně stejně jako předtím. Ani o kousek míň. Plamínek se rozdělil, a přesto ho nebylo méně. Ve tmě teď svítila dvě světla místo jednoho.` },
        { t: `„Děkuju,“ špitla Bětka. A pak už šli spolu, měsíc a rybka, vedle sebe.` },
        { t: `Kousek dál zhasla hvězda jednomu klukovi. Tentokrát se k ní natáhla Bětka se svou rybkou a špejli zase držel někdo velký. Pak zhasla sova a sově připálila hvězda. Světlo putovalo od lampionu k lampionu, jako když si děti podávají míč.` },
        { t: `U rybníka se průvod zastavil. Na hladině se objevila všechna světla ještě jednou, převrácená a třesoucí se. Sto světýlek nahoře a sto světýlek dole. Kachny na břehu otevřely jedno oko, podívaly se na tolik světel a zase ho zavřely.` },
        { t: `A všichni zazpívali ještě jednou, potichu, aby nevzbudili kachny: „Svítí, svítí lampička, malá jako jablíčko…“` },
        { t: `Domů se šlo pomalu. Ulice byly tiché, nohy těžké a lampion se houpal na klacíku. V oknech domů se tu a tam svítilo. Asi tam někdo četl pohádku.` },
        { t: `Doma ${p.nom} ${p.g('sfoukl', 'sfoukla')} svíčku.` },
        { t: `Lampion zůstal viset u okna. Kulatý, papírový a trochu unavený. Měsíc za oknem se na něj díval, jako by se díval do zrcadla.` },
        { t: `${c.H} ${g('zalezl', 'zalezla', 'zalezli')} pod peřinu.` },
        { t: `V postýlce bylo teplo a tma. Ale ne úplně. Za zavřenýma očima pořád svítila oranžová rybka a Bětčin úsměv. Takové světlo se nesfoukne.` },
        { t: `Jedno světýlko. Dvě světýlka. Sto světýlek. Všechna už spí.`, pause: 3 },
        { t: `Dobrou noc, ${c.h.voc}.`, pause: 4 },
      ];
    },
  },
  {
    id: 'karneval-masek',
    delka: 10,
    pro: 'vse',
    pozn: 'Dětský karneval. Ríša přijde v kostýmu kedlubny, který mu ušil děda, a ostatní se mu smějí, hrdina chvilku taky. Při hře „Masková mícha“ se všechny masky pomíchají a hrdina si vytáhne právě kedlubnovou čepici. Pozná, jak smích píchá, a otočí ho kedlubnovým tancem. Kdo je kdo, se pozná podle smíchu a chování, ne podle masky. Hrdina se Ríšovi omluví.',
    pouceni: 'Pod maskou zůstáváš sám sebou a smát se spolu je fajn, ale smát se někomu bolí.',
    free: false,
    cats: ['svatky', 'sranda'],
    ages: [3, 8],
    mood: 'adventure',
    cover: { emoji: '🎭', g1: '#7b1fa2', g2: '#81c784' },
    title: () => `Kdo je pod maskou?`,
    text: (c) => {
      const g = c.g, n = c.n, p = c.p1;
      return [
        { t: `V sobotu odpoledne byl ${c.inTown} velký dětský karneval.`, sfx: 'ding' },
        { t: `Celý týden se doma stříhalo, lepilo a malovalo. Z kartonu se vystřihly uši, ze staré ponožky ocásek a z kousku kožešinky čumáček. A nakonec ${n('byla maska hotová', 'byly masky hotové')}.` },
        { t: `${cap(c.animal)}! ${n('Zvíře, které má', 'Zvířata, která mají')} ${c.H} ze všech nejradši.` },
        { t: `Před zrcadlem se pak dlouho zkoušelo, jestli je zvíře dost zvířecí. Vousky namalované na tvářích, čumáček na gumičce, ocásek přišpendlený vzadu. Pár zvířecích zvuků na zkoušku, a hotovo!` },
        { t: `Sál voněl popcornem a konfetami. Pod stropem visely balónky, na pódiu hrála kapela a uprostřed tancoval klaun s červeným nosem. Jmenoval se Konfetík a smál se tak, že mu nos svítil.` },
        { t: `U dveří stáli dva kovbojové a hádali se, kdo z nich je šerif. Malá víla mávala hůlkou na každého, kdo šel kolem, a čekala, jestli se z něj stane žába. Zatím nic.` },
        { t: `A masky! Princezny, piráti, hasiči a jeden velký drak, kterému se ocas pořád zamotával do židlí. Ondra přišel jako rytíř. Šárka jako včelka. A Ríša…` },
        { t: `Ríša přišel jako kedlubna.` },
        { t: `Měl na sobě kulatý zelenofialový kabátek, na hlavě zelenou čepici s velkými listy a kolem krku fialový límec. Ušil mu to děda. Celé večery stříhal a šil a Ríša se těšil, až se ukáže.` },
        { t: `„Kedlubna!“ vykřikl jeden pirát. „Hahaha! Kdo by šel na karneval za kedlubnu?“ A smáli se piráti, smály se princezny a smál se i drak.` },
        { t: `${c.H} se ${g('zasmál', 'zasmála', 'zasmáli')} taky.` },
        { t: `Jen trošku. Jen proto, že se smáli všichni.` },
        { t: `Ríša zčervenal až po listy. Schoval se za sloup a už nevylezl.` },
        { t: `Pak Konfetík zatleskal. „A teď, milé masky, přichází hra, na kterou jsem se těšil celý rok! Masková mícha!“` },
        { t: `Každý musel sundat to, co měl na hlavě. Korunky, klobouky, přilby, uši i rohy. Všechno se naházelo do obrovského koše na prádlo. Konfetík si na hlavu posadil prázdný kbelík, aby to bylo spravedlivé, koš zamíchal, světla zhasla a z koše se tahalo poslepu.` },
        { t: `„A teď pozor!“ volal Konfetík. „Musíte najít, komu patří to, co máte na hlavě. Bez sundávání a bez jmen. Jen podle toho, jak kdo mluví, jak se směje a co dělá!“` },
        { t: `Světla se rozsvítila a v sále bylo najednou úplně jiné karnevalové království. Drak měl na hlavě korunku. Princezna pirátský klobouk. Hasič včelí tykadla a jedna včelka hasičskou přilbu. Nikdo nevěděl, kdo je kdo.`, sfx: 'magic' },
        { t: `„Nejsi náhodou princezna?“ zeptal se drak s korunkou piráta. „Arr! Nejsem!“ zahučel pirát s vílí čelenkou. „Já jsem šerif!“ ozval se kovboj s dračími rohy. „Ne, já jsem šerif!“ ozval se druhý kovboj, s králičíma ušima.` },
        { t: `${c.H} ${g('sáhl', 'sáhla', 'sáhli')} do koše.` },
        { t: `A ${g('vytáhl', 'vytáhla', 'vytáhli')} zelenou čepici s velkými listy${n('', ' a k ní fialový límec')}. Kedlubna.` },
        { t: `Sotva ${n('ji', 'je')} ${g('nasadil', 'nasadila', 'nasadili')}, ozvalo se zpod korunky: „Haha, kedlubna! Kedlubna!“ A pár dalších se přidalo.` },
        { t: `Bylo to zvláštní. Ten smích nebyl vůbec veselý. Píchal. Jako malý trn ve svetru, který není vidět, ale pořád je cítit.` },
        { t: `Takhle to tedy bylo Ríšovi. Za sloupem. Celou dobu.` },
        { t: `Utéct za sloup? To by šlo. Strhnout čepici a hodit ji zpátky do koše? To by šlo taky. Jenže pak by kedlubna zůstala sama. A Ríša za sloupem by viděl, že se jí smějí úplně všichni.` },
        { t: `${c.H} se ${g('narovnal', 'narovnala', 'narovnali')}.` },
        { t: `„Jo, ${n('jsem kedlubna', 'jsme kedlubny')},“ ${g('řekl', 'řekla', 'řekli')} nahlas. „A víte, co umí kedlubna? Kedlubnový tanec!“` },
        { t: `Dřep, výskok, otočka. Listy na čepici se třepetaly jako vlajky. Dřep, výskok, otočka.` },
        { t: `Drak s korunkou se přestal smát. Pak se zasmál jinak, vesele, a začal tancovat taky. Dřep, výskok, otočka. Přidala se princezna s pirátským kloboukem, hasič s tykadly a včelka s přilbou. Za chvíli tancoval kedlubnový tanec celý sál.` },
        { t: `Za sloupem se něco pohnulo. Vykoukly odtamtud dvě oči a hned zase zmizely.` },
        { t: `„Kapelo!“ zavolal Konfetík. „Hrajte kedlubnovou!“ A kapela, která žádnou kedlubnovou neznala, si ji rychle vymyslela. Měla jen dvě slova, kedlubna a hop, ale zpívala se dokola tak vesele, že ji všichni pobrukovali ještě týden.`, sfx: 'sparkle' },
        { t: `A pak se hledalo. Rytíře Ondru poznali všichni hned. Ondra se totiž směje jako škytající koza: hehe-hik, hehe-hik. A včelku Šárku taky, i když měla na hlavě hasičskou přilbu. Pořád ukazovala prstem a volala „tamhle, tamhle!“. Tak to dělá vždycky.` },
        { t: `Šárka si pak našla svoje tykadla. Měl je hasič, který se pořád škrábal na nose. Byl to Matyáš, ten se na nose škrábe, i když ho nic nesvědí. A pak se prodrala ke kedlubnové čepici.` },
        { t: `„${cap(c.h.voc)}!“ vykřikla.` },
        { t: `„Já vím, kdo ${n('jsi', 'jste')}! Pod těmi listy bych ${n('tě', 'vás')} nepoznala. Ale podle tance jo.“` },
        { t: `Masky se dají vyměnit. Smích, tanec a to, jak kdo ukazuje prstem, ale ne.` },
        { t: `Za sloupem ale pořád někdo stál. Někdo v kulatém zelenofialovém kabátku. Jenže na hlavě neměl listy. Při míše si potichu vzal první věc, která mu přišla pod ruku, a zase zalezl. Měl na hlavě masku s ušima a s čumáčkem. Kedlubna s hlavou zvířátka. To se nedalo splést.` },
        { t: `„Ahoj, Ríšo.“` },
        { t: `Ríša sklopil oči. „${n('V tvojí masce', 'Ve vaší masce')} se mi nikdo nesmál,“ řekl potichu. „Všichni říkali, že je krásná.“` },
        { t: `„A v tvojí kedlubně se smáli ${n('mně', 'nám')}. Moc to píchá. Promiň, že ${g('jsem se předtím taky smál', 'jsem se předtím taky smála', 'jsme se předtím taky smáli')}.“` },
        { t: `„Tvoje kedlubna je nejlepší maska v celém sále. Žádná jiná taková tu není. Děda ji šil jen pro tebe.“` },
        { t: `Ríša se zasmál. Poprvé za celé odpoledne. A ukázalo se, že se směje jako malý motorek: brrr-hihi, brrr-hihi.` },
        { t: `Pak si masky vyměnili zpátky. Ríša si nasadil listy, narovnal límec a vyšel zpoza sloupu. A tentokrát se nikdo nesmál. Tedy smál, ale jinak. Všichni volali: „Kedlubno, pojď tancovat!“` },
        { t: `Na konci karnevalu vyhlašoval Konfetík ceny. Za nejstrašidelnější masku vyhrál drak. Za nejtřpytivější jedna princezna. A cena za nejoriginálnější masku, takovou, kterou nikde nekoupíš, protože ji někdo ušil vlastníma rukama, putovala ke kedlubně.` },
        { t: `Ríšův děda tleskal ze všech nejhlasitěji a utíral si oči. Prý od konfet.` },
        { t: `Velkou čokoládovou medaili Ríša rozlámal na tolik kousků, kolik bylo kedlubnových tanečníků. Na každého vyšel jen drobeček. Ale chutnal.` },
        { t: `Na rozloučenou se domluvil plán na příští karneval. Půjde se společně. Jedna kedlubna, jedna mrkev a možná ještě hrášek. Celá zeleninová parta.` },
        { t: `Venku už byla tma a konfety se sypaly odevšad. Ze šál, z kapes, z bot. Jedna dokonce z ucha.` },
        { t: `Cestou domů se ${p.nom} ${p.g('zeptal', 'zeptala')}, jaký byl karneval.` },
        { t: `„Chvilku ${g('jsem byl kedlubna', 'jsem byla kedlubna', 'jsme byli kedlubny', 'jsme byly kedlubny')}. A pod maskou ${g('jsem byl pořád já', 'jsem byla pořád já', 'jsme byli pořád my')}. Smát se spolu je nejlepší. Ale smát se někomu, to píchá.“` },
        { t: `V koupelně se z tváří smyly vousky. Ze zrcadla se díval zase obyčejný obličej. Ten nejlepší, protože vlastní.` },
        { t: `Doma ${n('visí maska', 'visí masky')} na háčku u dveří. Uši, čumáček a ocásek ze staré ponožky. Do příštího karnevalu ${n('si odpočine', 'si odpočinou')}.` },
        { t: `Dobrou noc, ${c.h.voc}. Dobrou noc, kedlubno.`, pause: 3 },
      ];
    },
  },
]);
